/** The result of a check: the value, or the rules it breaks. */
export type CheckResult<T> = { readonly ok: true; readonly domain: typeof DOMAIN; readonly value: T } | { readonly ok: false; readonly domain: typeof DOMAIN; readonly failures: readonly Failure[] };

/** The types of the definitions, by name. */
export interface DefinitionTypes {
  readonly definition_name: DefinitionNameValue;
  readonly type_name: TypeName;
  readonly naming_request: NamingRequest;
  readonly named_type: NamedType;
  readonly version: Version;
  readonly from_version: FromVersion;
  readonly to_version: ToVersion;
  readonly reason: Reason;
  readonly version_change: VersionChange;
  readonly breaking_allowed: BreakingAllowed;
  readonly breaking_refused: BreakingRefused;
  readonly namespace_name: NamespaceName;
  readonly domain_name: DomainName;
  readonly part_kind: PartKind;
  readonly part_name: PartName;
  readonly urn: Urn;
  readonly part: Part;
  readonly part_urn: PartUrn;
  readonly candidate: Candidate;
  readonly namespace_candidate: NamespaceCandidate;
  readonly namespace_accepted: NamespaceAccepted;
  readonly namespace_refused: NamespaceRefused;
  readonly bound_rule: BoundRule;
  readonly old_bound: OldBound;
  readonly new_bound: NewBound;
  readonly bound_change: BoundChange;
  readonly direction: Direction;
  readonly bound_judged: BoundJudged;
  readonly code: Code;
  readonly fix: Fix;
  readonly code_request: CodeRequest;
  readonly code_fix: CodeFix;
  readonly standard_rule_name: StandardRuleName;
  readonly parameter_name: ParameterName;
  readonly parameter_names: ParameterNames;
  readonly rule_description: RuleDescription;
  readonly failure_text: FailureText;
  readonly standard_rule_request: StandardRuleRequest;
  readonly standard_rule: StandardRule;
  readonly function_name: FunctionName;
  readonly signature_text: SignatureText;
  readonly function_request: FunctionRequest;
  readonly function_signatures: FunctionSignatures;
  readonly step_text: StepText;
  readonly step_kind: StepKind;
  readonly step_request: StepRequest;
  readonly matched_step: MatchedStep;
  readonly unmatched_step: UnmatchedStep;
  readonly gate_number: GateNumber;
  readonly gate_name: GateName;
  readonly severity: Severity;
  readonly gate_problem: GateProblem;
  readonly gate_problems: GateProblems;
  readonly gate_facts: GateFacts;
  readonly gate_passed: GatePassed;
  readonly gate_failed: GateFailed;
  readonly message_text: MessageText;
  readonly argument_name: ArgumentName;
  readonly argument_text: ArgumentText;
  readonly message_argument: MessageArgument;
  readonly message_arguments: MessageArguments;
  readonly message_request: MessageRequest;
  readonly filled_text: FilledText;
  readonly filled_message: FilledMessage;
}

/** Checks a value against a definition: its structure, then each rule. */
export function check<D extends DefinitionName>(definition: D, value: unknown): CheckResult<DefinitionTypes[D]> {
  const failures: Failure[] = [];
  return CHECKS[definition](value, '', failures) ? { ok: true, domain: DOMAIN, value: value as DefinitionTypes[D] } : { ok: false, domain: DOMAIN, failures };
}

/** What an operation answers: one of its outputs, by name, and its value. */
export interface Answer<O extends string, V> {
  readonly output: O;
  readonly value: V;
}

/** An answer of the core: answer('booking', booking). */
export function answer<O extends string, V>(output: O, value: V): Answer<O, V> {
  return { output, value };
}

/** The answers of to_type_name. */
export type ToTypeNameAnswer = Answer<"named_type", NamedType>;

/** The answers of judge_version_change. */
export type JudgeVersionChangeAnswer = Answer<"breaking_allowed", BreakingAllowed> | Answer<"breaking_refused", BreakingRefused>;

/** The answers of name_part. */
export type NamePartAnswer = Answer<"part_urn", PartUrn>;

/** The answers of check_namespace. */
export type CheckNamespaceAnswer = Answer<"namespace_accepted", NamespaceAccepted> | Answer<"namespace_refused", NamespaceRefused>;

/** The answers of judge_weaker_contract. */
export type JudgeWeakerContractAnswer = Answer<"breaking_allowed", BreakingAllowed> | Answer<"breaking_refused", BreakingRefused>;

/** The answers of judge_bound_change. */
export type JudgeBoundChangeAnswer = Answer<"bound_judged", BoundJudged>;

/** The answers of fix_of. */
export type FixOfAnswer = Answer<"code_fix", CodeFix>;

/** The answers of describe_standard_rule. */
export type DescribeStandardRuleAnswer = Answer<"standard_rule", StandardRule>;

/** The answers of signatures_of. */
export type SignaturesOfAnswer = Answer<"function_signatures", FunctionSignatures>;

/** The answers of match_step. */
export type MatchStepAnswer = Answer<"matched_step", MatchedStep> | Answer<"unmatched_step", UnmatchedStep>;

/** The answers of judge_gate. */
export type JudgeGateAnswer = Answer<"gate_passed", GatePassed> | Answer<"gate_failed", GateFailed>;

/** The answers of fill_message. */
export type FillMessageAnswer = Answer<"filled_message", FilledMessage>;

/** The core: a function for each operation, from its input to one of its answers. */
export interface DomainCore {
  /** Name the TypeScript type of a definition, as the generated file does */
  readonly to_type_name: (input: NamingRequest) => ToTypeNameAnswer;
  /** Whether the versions of two manifests allow a breaking change, as diff judges it by semver */
  readonly judge_version_change: (input: VersionChange) => JudgeVersionChangeAnswer;
  /** The URN of a part, as the generated file, diff and gate 5 give it */
  readonly name_part: (input: Part) => NamePartAnswer;
  /** Whether a text is a URN namespace, as the manifest takes it */
  readonly check_namespace: (input: NamespaceCandidate) => CheckNamespaceAnswer;
  /** Whether the versions of two manifests allow a weaker contract, as gate 5 judges it */
  readonly judge_weaker_contract: (input: VersionChange) => JudgeWeakerContractAnswer;
  /** Whether a new bound of a standard rule accepts fewer values or more, as diff and gate 5 judge it */
  readonly judge_bound_change: (input: BoundChange) => JudgeBoundChangeAnswer;
  /** The fix of a code, which each report of the code shows */
  readonly fix_of: (input: CodeRequest) => FixOfAnswer;
  /** A standard rule, with its parameters, what it checks and what its failure says */
  readonly describe_standard_rule: (input: StandardRuleRequest) => DescribeStandardRuleAnswer;
  /** The types that a function of the rule language takes and gives */
  readonly signatures_of: (input: FunctionRequest) => SignaturesOfAnswer;
  /** Whether a step text is a step of urn-forge, and which one, as Cucumber reads it */
  readonly match_step: (input: StepRequest) => MatchStepAnswer;
  /** Whether a gate passes, from the problems that it found */
  readonly judge_gate: (input: GateFacts) => JudgeGateAnswer;
  /** The failure message of a use of a rule, with its arguments in place, as a failure gives it */
  readonly fill_message: (input: MessageRequest) => FillMessageAnswer;
}

